llm_calls.content:
{
  "task_summary": "Predict whether an ACS individual is employed versus not employed.",
  "ranking": [
    {
      "rank": 1,
      "feature": "AGEP",
      "rationale": "Employment participation varies strongly and consistently over the life cycle."
    },
    {
      "rank": 2,
      "feature": "DIS",
      "rationale": "Overall disability status directly affects ability to work and is broadly portable across states."
    },
    {
      "rank": 3,
      "feature": "SCHL",
      "rationale": "Educational attainment is a stable predictor of labor-market attachment."
    },
    {
      "rank": 4,
      "feature": "DREM",
      "rationale": "Cognitive difficulty can substantially affect employability across locations."
    },
    {
      "rank": 5,
      "feature": "MAR",
      "rationale": "Marital status captures household and life-stage factors related to employment."
    },
    {
      "rank": 6,
      "feature": "RELP",
      "rationale": "Household relationship encodes life stage and dependency patterns relevant to work."
    },
    {
      "rank": 7,
      "feature": "MIL",
      "rationale": "Military service status relates to labor-force status, though partly cohort- and sex-confounded."
    },
    {
      "rank": 8,
      "feature": "DEYE",
      "rationale": "Vision difficulty may affect work capacity but is narrower than general disability."
    },
    {
      "rank": 9,
      "feature": "DEAR",
      "rationale": "Hearing difficulty can affect employment but is generally less predictive than broader disability measures."
    },
    {
      "rank": 10,
      "feature": "MIG",
      "rationale": "Recent mobility can correlate with job changes but may reflect local housing and state-specific patterns."
    },
    {
      "rank": 11,
      "feature": "CIT",
      "rationale": "Citizenship can affect labor-market access but risks encoding immigrant and regional composition."
    },
    {
      "rank": 12,
      "feature": "NATIVITY",
      "rationale": "Nativity is only indirectly related to employment and may encode geographic demographic artifacts."
    },
    {
      "rank": 13,
      "feature": "ESP",
      "rationale": "Parental employment status is limited in applicability and may mostly capture household artifacts."
    },
    {
      "rank": 14,
      "feature": "SEX",
      "rationale": "Sex is predictive through labor-market disparities but is a demographic shortcut rather than a robust semantic cause."
    },
    {
      "rank": 15,
      "feature": "RAC1P",
      "rationale": "Race is predictive mainly through structural and regional disparities, making it brittle for OOD generalization."
    },
    {
      "rank": 16,
      "feature": "ANC",
      "rationale": "Ancestry is weakly causal and likely to encode geography and population-composition artifacts."
    }
  ]
}
